css:
.a3s h2{font-size:15px;margin:18px 0 6px;padding-bottom:4px;border-bottom:2px solid #333;text-transform:uppercase;letter-spacing:.04em}
.a3s h3{font-size:13px;margin:14px 0 4px}
.a3s table{width:100%;border-collapse:collapse;margin-bottom:10px;font-size:11px}
.a3s th,.a3s td{border:1px solid #999;padding:5px 7px;vertical-align:top;text-align:left}
.a3s th{background:#eee;font-weight:600}
.a3s .num{text-align:right;white-space:nowrap}
.a3s .muted{color:#555;font-size:10.5px}
.a3s .note{background:#f6f6f6;border-left:3px solid #666;padding:8px 10px;margin:10px 0;font-size:11px}
.a3s .cover p{margin:0 0 8px;text-align:justify}
.a3s ol,.a3s ul{margin:0 0 10px 18px;padding:0}
.a3s li{margin-bottom:4px}
.a3s .sig{margin-top:28px}
.a3s .page-break{page-break-before:always}
